const queryArr = $('Rekap').all();
const query = (queryArr.length > 0) ? (queryArr[0].json.query || {}) : {};
const dari   = query.dari   || null;
const sampai = query.sampai || null;

function parseJam(str, fallback) {
  if (!str) return fallback;
  const parts = str.split(':').map(Number);
  if (parts.length < 2 || isNaN(parts[0]) || isNaN(parts[1])) return fallback;
  return parts[0] * 60 + parts[1];
}
const JAM_MASUK_STANDAR  = parseJam(query.jam_masuk,  8 * 60);
const JAM_PULANG_STANDAR = parseJam(query.jam_pulang, 14 * 60 + 30);

let HARI_KERJA_PERIODE = parseInt(query.hari_kerja) || 0;
let hariLiburSet = new Set();
try {
  const liburArr = JSON.parse(decodeURIComponent(query.libur || '[]'));
  if (Array.isArray(liburArr)) hariLiburSet = new Set(liburArr);
} catch(_) {}

if (!HARI_KERJA_PERIODE && dari && sampai) {
  const d = new Date(dari + 'T00:00:00');
  const s = new Date(sampai + 'T00:00:00');
  while (d <= s) {
    const day = d.getDay();
    const tgl = d.toISOString().split('T')[0];
    if (day !== 0 && day !== 6 && !hariLiburSet.has(tgl)) HARI_KERJA_PERIODE++;
    d.setDate(d.getDate() + 1);
  }
}

const JAM_PER_HARI    = (JAM_PULANG_STANDAR - JAM_MASUK_STANDAR) / 60;
const JAM_KERJA_WAJIB = parseFloat((JAM_PER_HARI * HARI_KERJA_PERIODE).toFixed(1));

function toMenit(jamStr) {
  const s = String(jamStr || '').replace(/\s.*$/, '').split(':');
  if (s.length < 2) return null;
  const h = parseInt(s[0]), m = parseInt(s[1]);
  return (isNaN(h) || isNaN(m)) ? null : h * 60 + m;
}

function fmtMenit(tot) {
  if (!tot || tot <= 0) return '0m';
  const h = Math.floor(tot / 60), m = tot % 60;
  return (h === 0 ? '' : h + 'j ') + (m + 'm');
}

function toHHMM(totalMinutes) {
  if (!totalMinutes || totalMinutes <= 0) return '00:00';
  const h = Math.floor(Math.abs(totalMinutes) / 60);
  const m = Math.abs(totalMinutes) % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function getDisiplin(pct) {
  if (pct === null || pct === undefined) return { pct: null, label: '—', level: 0 };
  if (pct >= 95) return { pct, label: 'Sangat Disiplin', level: 4 };
  if (pct >= 80) return { pct, label: 'Disiplin',        level: 3 };
  if (pct >= 60) return { pct, label: 'Cukup',           level: 2 };
  return              { pct, label: 'Kurang',            level: 1 };
}

function getKehadiran(pct) {
  if (pct === null || pct === undefined) return { pct: null, label: '—', level: 0 };
  if (pct >= 95) return { pct, label: 'Sangat Rajin', level: 4 };
  if (pct >= 80) return { pct, label: 'Rajin',        level: 3 };
  if (pct >= 60) return { pct, label: 'Cukup',        level: 2 };
  return              { pct, label: 'Sering Absen',   level: 1 };
}

