// âœ… Validasi radius + IP per-lokasi
//
//  Kolom ip_range di tabel lokasiabsen berisi satu atau lebih
//  IP/CIDR dipisah koma. Contoh: "36.84.229.0/24, 110.136.216.0/24"
//
//  Aturan per baris lokasi:
//  â€¢ ip_range NULL / kosong â†’ hanya cek radius (tanpa batasan IP)
//  â€¢ ip_range diisi         â†’ user harus dalam radius DAN IP cocok
//
//  Prioritas hasil:
//  1. Lolos radius + IP (atau radius saja jika ip_range kosong) â†’ TERIMA
//  2. Dalam radius tapi semua IP gagal                          â†’ BUKAN_JARINGAN_KANTOR
//  3. Semua lokasi di luar radius                               â†’ DILUAR_RADIUS
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
if (!lokasiItems.length) return tolak('LOKASI_TIDAK_ADA', 'Data lokasi kantor belum dikonfigurasi.');

const accuracyBuffer = Math.min(accuracy, 50);
let lokasiValid   = null;  // lokasi yang lolos radius + IP
let lokasiIPGagal = null;  // lokasi yang lolos radius tapi IP tidak cocok

for (const lok of lokasiItems) {
  const namaLok = lok.Nama_Lokasi || lok.nama_lokasi || 'Kantor';
  const jarak   = haversine(lat, lng, parseFloat(lok.latitude), parseFloat(lok.longitude));

  // Di luar radius â†’ lewati
  if (jarak > (parseFloat(lok.radius) || 100) + accuracyBuffer) continue;

  // â”€â”€ Dalam radius: cek ip_range jika kolom diisi â”€â”€
  const ipRangeRaw = String(lok.ip_range || '').trim();

  if (ipRangeRaw) {
    // Lokasi ini punya pembatasan IP
    if (!ipCek) {
      // IP tidak bisa dideteksi â†’ tolak demi keamanan
      return tolak('IP_TIDAK_TERDETEKSI',
        `Lokasi ${namaLok} memerlukan jaringan kantor tetapi alamat IP Anda tidak dapat dideteksi.`);
    }

    const rangeList = ipRangeRaw.split(',').map(s => s.trim()).filter(Boolean);
    if (!rangeList.some(cidr => ipInCIDR(ipCek, cidr))) {
      // Dalam radius tapi IP tidak cocok â€” catat & coba lokasi berikutnya
      lokasiIPGagal = lokasiIPGagal || namaLok;
      continue;
    }
  }

  // Lolos (radius + IP cocok, atau lokasi tanpa ip_range)
  lokasiValid = namaLok;
  break;
}

if (!lokasiValid) {
  if (lokasiIPGagal) {
    return tolak('BUKAN_JARINGAN_KANTOR',
      `Anda berada di area ${lokasiIPGagal} namun bukan dari jaringan WiFi kantor yang diizinkan. IP Anda: ${ipCek}.`);
  }
  let jarakMin = Infinity, namaMin = '';
  for (const lok of lokasiItems) {
    const j = haversine(lat, lng, parseFloat(lok.latitude), parseFloat(lok.longitude));
    if (j < jarakMin) { jarakMin = j; namaMin = lok.Nama_Lokasi || lok.nama_lokasi || 'Kantor'; }
  }
  return tolak('DILUAR_RADIUS',
    `Anda berada ${Math.round(jarakMin)}m dari ${namaMin}. Absen hanya bisa di area kantor.`);
}

